//! Tests for the composable revocation coverage determination.
//!
//! The binary assets are generated by `assets/revocation/gen_revocation_assets.py`.

use x509_parser::certificate::X509Certificate;
use x509_parser::prelude::*;
use x509_parser::revocation::*;
use x509_parser::time::ASN1Time;

fn load_crl(bytes: &[u8]) -> CertificateRevocationList<'_> {
    parse_x509_crl(bytes).expect("could not parse CRL").1
}

fn load_cert(bytes: &[u8]) -> X509Certificate<'_> {
    parse_x509_certificate(bytes)
        .expect("could not parse certificate")
        .1
}

const AT_TIME: i64 = 1_767_225_600; // 2026-01-01T00:00:00Z, inside the fixtures validity

fn options() -> CrlCoverageOptions {
    CrlCoverageOptions {
        at_time: Some(ASN1Time::from_timestamp(AT_TIME).unwrap()),
        check_distribution_points: false,
    }
}

#[test]
fn parse_delta_crl_indicator_and_accessors() {
    let crl = load_crl(include_bytes!("../assets/revocation/delta_101.der"));
    assert!(crl.is_delta_crl());
    assert_eq!(
        crl.delta_crl_indicator().map(|n| n.to_string()).as_deref(),
        Some("100")
    );
    assert_eq!(
        crl.crl_number().map(|n| n.to_string()).as_deref(),
        Some("101")
    );

    let full = load_crl(include_bytes!("../assets/revocation/full_fresh.der"));
    assert!(!full.is_delta_crl());
    assert!(full.delta_crl_indicator().is_none());
    assert!(full.issuing_distribution_point().is_none());
}

#[test]
fn clean_cert_against_fresh_full_crl_is_covered_and_clean() {
    let crl = load_crl(include_bytes!("../assets/revocation/full_fresh.der"));
    let cert = load_cert(include_bytes!("../assets/revocation/cert_clean.der"));

    let status = CrlCoverage::check(CrlScope::new(&crl), &cert, options());
    assert!(status.is_covered());
    let coverage = status.coverage();
    assert!(coverage.matched.is_empty());
    assert!(coverage.clean());
    assert!(!coverage.is_revoked());
}

#[test]
fn revoked_cert_is_detected_with_reason() {
    let crl = load_crl(include_bytes!("../assets/revocation/full_fresh.der"));
    let cert = load_cert(include_bytes!("../assets/revocation/cert_revoked.der"));

    let status = CrlCoverage::check(CrlScope::new(&crl), &cert, options());
    assert!(status.is_covered());
    let coverage = status.coverage();
    assert!(coverage.is_revoked());
    assert!(!coverage.clean());
    assert_eq!(coverage.matched.len(), 1);
    assert_eq!(coverage.matched[0].reason, Some(ReasonCode::KeyCompromise));
    assert_eq!(coverage.matched[0].state, EntryState::Revoked);
}

#[test]
fn expired_crl_blocks_clean_but_keeps_revocation() {
    let expired = load_crl(include_bytes!("../assets/revocation/full_expired.der"));
    let clean_cert = load_cert(include_bytes!("../assets/revocation/cert_clean.der"));
    let revoked_cert = load_cert(include_bytes!("../assets/revocation/cert_revoked.der"));

    let status = CrlCoverage::check(CrlScope::new(&expired), &clean_cert, options());
    assert!(status.is_covered());
    assert!(status.coverage().warnings.contains(&CrlWarning::Expired));
    assert!(!status.coverage().clean(), "expired CRL must not be clean");

    // revocation remains observable even on an expired CRL
    let status = CrlCoverage::check(CrlScope::new(&expired), &revoked_cert, options());
    assert!(status.coverage().is_revoked());
}

#[test]
fn missing_next_update_is_warned() {
    let minimal = load_crl(include_bytes!("../assets/minimal.crl"));
    let cert = load_cert(include_bytes!("../assets/revocation/cert_clean.der"));
    let status = CrlCoverage::check(CrlScope::new(&minimal), &cert, options());
    assert!(status
        .coverage()
        .warnings
        .contains(&CrlWarning::NoNextUpdate));
    assert!(!status.coverage().clean());
}

#[test]
fn reason_partition_gives_not_covered_for_excluded_reason() {
    let crl = load_crl(include_bytes!("../assets/revocation/only_reasons.der"));
    let scope = CrlScope::new(&crl);
    assert!(scope.warnings().contains(&CrlWarning::PartitionedByReason));

    // keyCompromise is inside the partition: the revoked cert is covered
    let revoked_cert = load_cert(include_bytes!("../assets/revocation/cert_revoked.der"));
    let status = CrlCoverage::check(scope.clone(), &revoked_cert, options());
    assert!(status.is_covered());
    assert!(status.coverage().is_revoked());

    // a clean cert cannot be declared clean for reasons outside the partition
    let clean_cert = load_cert(include_bytes!("../assets/revocation/cert_clean.der"));
    let status = CrlCoverage::check(scope, &clean_cert, options());
    assert!(status.is_not_covered());
}

#[test]
fn ca_only_idp_excludes_end_entity_cert() {
    let crl = load_crl(include_bytes!("../assets/revocation/only_ca.der"));
    let cert = load_cert(include_bytes!("../assets/revocation/cert_clean.der"));
    let scope = CrlScope::new(&crl);
    assert!(scope.excludes_certificate(&cert));

    let status = CrlCoverage::check(scope, &cert, options());
    assert!(status.is_not_covered());

    // the CA certificate itself is a CA cert and remains covered
    let ca = load_cert(include_bytes!("../assets/revocation/ca.der"));
    let ca_only_crl = load_crl(include_bytes!("../assets/revocation/only_ca.der"));
    let status = CrlCoverage::check(CrlScope::new(&ca_only_crl), &ca, options());
    assert!(status.is_covered());
}

#[test]
fn unknown_critical_extension_blocks_clean() {
    let crl = load_crl(include_bytes!("../assets/revocation/unknown_critical.der"));
    let cert = load_cert(include_bytes!("../assets/revocation/cert_clean.der"));
    let scope = CrlScope::new(&crl);
    assert!(scope.has_unrecognized_critical_extension());

    let status = CrlCoverage::check(scope, &cert, options());
    assert!(status
        .coverage()
        .warnings
        .contains(&CrlWarning::UnrecognizedCriticalExtension));
    assert!(!status.coverage().clean());
}

#[test]
fn duplicate_serial_is_a_deterministic_conflict() {
    let crl = load_crl(include_bytes!("../assets/revocation/duplicate_serial.der"));
    let duplicate_cert = load_cert(include_bytes!("../assets/revocation/cert_duplicate.der"));

    let status = CrlCoverage::check(CrlScope::new(&crl), &duplicate_cert, options());
    assert!(status.is_conflict());
    assert!(status
        .coverage()
        .conflicts
        .contains(&CrlConflict::DuplicateSerial));
    // identical duplicate entries are not flagged as inconsistent
    assert!(!status
        .coverage()
        .conflicts
        .contains(&CrlConflict::InconsistentEntries));
    assert!(!status.coverage().clean());
}

#[test]
fn inconsistent_duplicate_entries_report_both_conflicts() {
    let crl = load_crl(include_bytes!(
        "../assets/revocation/duplicate_inconsistent.der"
    ));
    let duplicate_cert = load_cert(include_bytes!("../assets/revocation/cert_duplicate.der"));

    let status = CrlCoverage::check(CrlScope::new(&crl), &duplicate_cert, options());
    assert!(status.is_conflict());
    let conflicts = &status.coverage().conflicts;
    assert!(conflicts.contains(&CrlConflict::DuplicateSerial));
    assert!(conflicts.contains(&CrlConflict::InconsistentEntries));
}

#[test]
fn remove_from_crl_on_full_crl_is_a_conflict() {
    let crl = load_crl(include_bytes!(
        "../assets/revocation/remove_from_crl_full.der"
    ));
    let hold_cert = load_cert(include_bytes!("../assets/revocation/cert_hold.der"));

    let status = CrlCoverage::check(CrlScope::new(&crl), &hold_cert, options());
    assert!(status.is_conflict());
    assert!(status
        .coverage()
        .conflicts
        .contains(&CrlConflict::RemoveFromCrlOutsideDelta));
    // conflicts never allow a clean result
    assert!(!status.coverage().clean());
}

#[test]
fn indirect_crl_resolves_certificate_issuer() {
    let crl = load_crl(include_bytes!("../assets/revocation/indirect.der"));
    let scope = CrlScope::new(&crl);
    assert!(scope.is_indirect());

    // cert issued by the other CA: the certificateIssuer extension must match
    let indirect_cert = load_cert(include_bytes!("../assets/revocation/cert_indirect.der"));
    let status = CrlCoverage::check(scope, &indirect_cert, options());
    assert!(status.is_covered());
    assert!(status.coverage().is_revoked());
    assert_eq!(status.coverage().matched.len(), 1);

    // a cert issued by the CRL issuer does not match this entry: no entry applies
    let own_cert = load_cert(include_bytes!("../assets/revocation/cert_clean.der"));
    let indirect_crl = load_crl(include_bytes!("../assets/revocation/indirect.der"));
    let status = CrlCoverage::check(CrlScope::new(&indirect_crl), &own_cert, options());
    assert!(status.coverage().matched.is_empty());

    // indirect CRL entry without certificateIssuer cannot be attributed to a cert issued by
    // another CA: this is reported as a deterministic conflict
    let no_issuer_crl = load_crl(include_bytes!(
        "../assets/revocation/indirect_no_issuer.der"
    ));
    let status = CrlCoverage::check(CrlScope::new(&no_issuer_crl), &indirect_cert, options());
    assert!(status.is_conflict());
    assert!(status
        .coverage()
        .conflicts
        .contains(&CrlConflict::IndirectCrlUnknownIssuer));
}

#[test]
fn base_plus_delta_composes_into_clean_and_revoked() {
    let base = load_crl(include_bytes!("../assets/revocation/full_fresh.der"));
    let delta = load_crl(include_bytes!("../assets/revocation/delta_101.der"));

    let mut check = RevocationCheck::with_base_crl(&base);
    check.add_delta_crl(&delta);

    // clean serial: base has no entry and delta does not touch it
    let clean_cert = load_cert(include_bytes!("../assets/revocation/cert_clean.der"));
    let status = check.evaluate(&clean_cert);
    assert!(status.is_clean());

    // serial revoked in the base stays revoked
    let revoked_cert = load_cert(include_bytes!("../assets/revocation/cert_revoked.der"));
    let status = check.evaluate(&revoked_cert);
    assert!(status.is_revoked());

    // hold serial only present on the delta is revoked/on hold
    let hold_cert = load_cert(include_bytes!("../assets/revocation/cert_hold.der"));
    let status = check.evaluate(&hold_cert);
    assert!(status.is_revoked());
}

#[test]
fn delta_without_base_never_allows_clean() {
    let delta = load_crl(include_bytes!("../assets/revocation/delta_101.der"));
    let clean_cert = load_cert(include_bytes!("../assets/revocation/cert_clean.der"));

    let check = RevocationCheck::new();
    let mut check = check;
    check.add_delta_crl(&delta);
    let status = check.evaluate(&clean_cert);
    assert!(status.is_unknown());
}

#[test]
fn delta_with_wrong_base_number_is_unknown() {
    let base = load_crl(include_bytes!("../assets/revocation/full_fresh.der"));
    let bad_delta = load_crl(include_bytes!("../assets/revocation/delta_wrong_base.der"));
    let clean_cert = load_cert(include_bytes!("../assets/revocation/cert_clean.der"));

    let mut check = RevocationCheck::with_base_crl(&base);
    check.add_delta_crl(&bad_delta);
    let status = check.evaluate(&clean_cert);
    assert!(status.is_unknown());
    assert!(!status.is_clean());
}

#[test]
fn expired_base_makes_composed_result_unknown() {
    let expired = load_crl(include_bytes!("../assets/revocation/full_expired.der"));
    let clean_cert = load_cert(include_bytes!("../assets/revocation/cert_clean.der"));

    let status = RevocationCheck::with_base_crl(&expired)
        .with_options(options())
        .evaluate(&clean_cert);
    assert!(status.is_unknown());
}

#[test]
fn unknown_critical_crl_makes_composed_result_unknown() {
    let crl = load_crl(include_bytes!("../assets/revocation/unknown_critical.der"));
    let clean_cert = load_cert(include_bytes!("../assets/revocation/cert_clean.der"));

    let status = RevocationCheck::with_base_crl(&crl).evaluate(&clean_cert);
    assert!(status.is_unknown());
}

#[test]
fn scope_not_covered_propagates_to_unknown() {
    let ca_only = load_crl(include_bytes!("../assets/revocation/only_ca.der"));
    let clean_cert = load_cert(include_bytes!("../assets/revocation/cert_clean.der"));

    let status = RevocationCheck::with_base_crl(&ca_only).evaluate(&clean_cert);
    assert!(status.is_unknown());
}
